const menu=document.querySelector('.menu');
menu.addEventListener('click',()=>{const open=document.querySelector('header').classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.textContent=open?'×':'☰';});
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('header').classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.textContent='☰';}));
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelectorAll('[data-category]').forEach(p=>p.hidden=button.dataset.filter!=='all'&&p.dataset.category!==button.dataset.filter);}));
const projects={
pipeline:{label:'ENTERPRISE DATA ENGINEERING',title:'Reliable data, at enterprise scale',body:'At PRAN-RFL Group, I architected and deployed 20+ ETL/ELT pipelines processing 6–8 million records daily. I designed a MySQL Shadow Database architecture with stored procedures and automated schedulers to separate transactional and analytical workloads, then migrated and synchronized critical data into MS SQL Server. The work focused on production stability, consistency, and reliable data availability.',tools:'Talend ETL · MySQL · MS SQL Server · Stored procedures · Job scheduling · OLTP/OLAP architecture'},
bi:{label:'BUSINESS INTELLIGENCE & AUTOMATION',title:'From reporting to decision support',body:'I built and maintained SSAS Cube data models for Power BI on datasets exceeding 100 million rows, with scheduled refresh. I developed 40+ interactive dashboards and executive reports embedded into internal ERP platforms. Working with more than 40 business units, I gathered requirements and defined KPIs. End-to-end automation eliminated 65% of manual recurring MIS reporting.',tools:'Power BI · SSAS · DAX · SQL · Embedded analytics · ERP integration'},
conflict:{label:'SPATIO-TEMPORAL RESEARCH',title:'Understanding conflict across space & time',body:'This project developed and compared artificial neural network and Spatio-Temporal Graph Convolutional Network models to forecast armed conflict events in Bangladesh using geospatial data. The research brings spatial relationships and temporal patterns into the modelling process. It was supported by the National Science & Technology Fellowship in 2025.',tools:'Artificial neural networks · STGCN · Geospatial analysis · Statistical modelling'},
sentiment:{label:'NATURAL LANGUAGE PROCESSING',title:'Finding sentiment in the headlines',body:'I built comparative machine learning classification models for sentiment analysis of Bangladeshi English news headlines. The project used TF-IDF vectorization and explored classification performance with XGBoost. It combines text preprocessing, feature representation, and comparative modelling.',tools:'NLP · TF-IDF · XGBoost · Machine learning'}
};
const dialog=document.querySelector('dialog');document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>{const p=projects[b.dataset.project];document.querySelector('#dialog-label').textContent=p.label;document.querySelector('#dialog-title').textContent=p.title;document.querySelector('#dialog-body').textContent=p.body;document.querySelector('#dialog-tools').textContent=p.tools;dialog.setAttribute('aria-labelledby','dialog-title');dialog.showModal();}));document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.querySelector('#year').textContent=new Date().getFullYear();document.querySelector('#copy-email').addEventListener('click',async e=>{const b=e.currentTarget;try{await navigator.clipboard.writeText('dsakyf100@gmail.com');b.textContent='Email copied ✓';setTimeout(()=>b.textContent='Copy email ⧉',2500);}catch{b.textContent='dsakyf100@gmail.com';}});
